Then write a script:
```js
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('requestfailed', r => errors.push('reqfail: ' + r.url() + ' ' + (r.failure()&&r.failure().errorText)));
  await page.goto('http://localhost/index.html', { waitUntil: 'networkidle', timeout: 60000 });
  // Wait for the index selection to be populated
  await page.waitForTimeout(3000);
  const options = await page.$eval('#chooseIndex', el => Array.from(el.options).map(o => o.value));
  console.log('INDEX_OPTIONS:', JSON.stringify(options));
  const title = await page.title();
  console.log('TITLE:', title);
  // Select the first index and run
  ...
  console.log('JS_ERRORS:', JSON.stringify(errors.filter(e=>!e.includes('favicon'))));
  await browser.close();
})();
```

